#### Phase 3: Publish Events

**1. Create and Publish Event**

Python example:
```python
from datetime import datetime
import uuid

def publish_claim_status_change(claim_id, new_status, previous_status, changed_by, correlation_id):
    """Publish claim status change event"""

    event = {
        "eventId": str(uuid.uuid4()),
        "eventType": "ClaimStatusChanged",
        "timestamp": datetime.utcnow().isoformat() + 'Z',
        "correlationId": correlation_id,
        "claimId": claim_id,
        "newStatus": new_status,
        "previousStatus": previous_status,
        "changedBy": changed_by
    }

    try:
        # Synchronous publish with automatic schema validation
        result = publisher.publish(
            event_type="ClaimStatusChanged",
            event=event,
            key=claim_id  # Optional: for ordering in Kafka
        )

        logger.info(
            f"Published ClaimStatusChanged event",
            extra={
                "event_id": event["eventId"],
                "claim_id": claim_id,
                "correlation_id": correlation_id,
                "publish_latency_ms": result.latency_ms
            }
        )

        return result

    except ValidationError as e:
        logger.error(f"Schema validation failed: {e}")
        raise

    except PublishError as e:
        logger.error(f"Failed to publish event after retries: {e}")
        # Consider publishing to dead letter queue or alerting
        raise
```

Java example:
```java
import com.gainwell.eaas.Event;
import com.gainwell.eaas.PublishResult;

public PublishResult publishClaimStatusChange(
    String claimId,
    String newStatus,
    String previousStatus,
    String changedBy,
    String correlationId) {

    Event event = Event.builder()
        .eventId(UUID.randomUUID().toString())
        .eventType("ClaimStatusChanged")
        .timestamp(Instant.now())
        .correlationId(correlationId)
        .payload(Map.of(
            "claimId", claimId,
            "newStatus", newStatus,
            "previousStatus", previousStatus,
            "changedBy", changedBy
        ))
        .build();

    try {
        PublishResult result = publisher.publish(
            "ClaimStatusChanged",
            event,
            claimId // key for ordering
        );

        logger.info("Published ClaimStatusChanged event: eventId={}, claimId={}, latency={}ms",
            event.getEventId(), claimId, result.getLatencyMs());

        return result;

    } catch (ValidationException e) {
        logger.error("Schema validation failed", e);
        throw new EventPublishException("Invalid event schema", e);

    } catch (PublishException e) {
        logger.error("Failed to publish event after retries", e);
        // Implement fallback strategy (DLQ, alerting, etc.)
        throw new EventPublishException("Event publish failed", e);
    }
}
```

**2. Asynchronous Publishing (Optional)**

For high-throughput scenarios:

Python example:
```python
# Asynchronous publish with callback
def on_publish_complete(result):
    if result.success:
        logger.info(f"Event published: {result.event_id}")
    else:
        logger.error(f"Publish failed: {result.error}")

# Non-blocking publish
publisher.publish_async(
    event_type="ClaimStatusChanged",
    event=event,
    key=claim_id,
    callback=on_publish_complete
)
```
